// The permissions table.
// Generated by tylix make:permissions. Yours to edit.
//
// Read permissions with it; create and delete them through `permissions`
// (app/permissions) so roles and the cache stay in step.
import { Model } from '@tylix/orm'

export class Permission extends Model {
  static table = 'permissions'
  static fillable = ['name', 'description']

  static async findByName(name: string) {
    return this.where('name', name).first()
  }
}
